import {seed} from './data.js';
import {STORAGE_KEY,PREF_KEY,escapeHTML as esc,tehranDay,addDays,initialState,readState,persistState,feeFor,sessionConflict} from './state.js';

let prefs={lang:'fa',dark:false};
try{prefs={...prefs,...JSON.parse(localStorage.getItem(PREF_KEY)||'{}')}}catch{}
let storage;try{storage=localStorage}catch{storage={getItem:()=>null,setItem:()=>{throw Error('Storage unavailable')},removeItem:()=>{}}}
let state=readState(storage,seed),route=location.pathname,query=new URLSearchParams(location.search),filters={query:'',language:'all',format:'all'},selectedDay=tehranDay();
const app=document.querySelector('#app'),overlay=document.querySelector('#overlay');
const t=(fa,en)=>prefs.lang==='fa'?fa:en;
const n=value=>new Intl.NumberFormat(prefs.lang==='fa'?'fa-IR':'en-US',{maximumFractionDigits:2}).format(value);
const money=(value,currency='TOMAN')=>n(value)+' '+(currency==='USD'?t('دلار','USD'):t('تومان','toman'));
const date=(value,options={day:'numeric',month:'long'})=>new Intl.DateTimeFormat(prefs.lang==='fa'?'fa-IR':'en-GB',{timeZone:'Asia/Tehran',...options}).format(new Date(value+'T12:00:00Z'));
const langs={en:['انگلیسی','English'],de:['آلمانی','German'],fr:['فرانسوی','French'],es:['اسپانیایی','Spanish'],tr:['ترکی','Turkish'],ar:['عربی','Arabic'],fa:['فارسی','Persian'],it:['ایتالیایی','Italian']};
const categories={learning:['یادگیری زبان','Learning'],conversation:['مکالمه','Conversation'],exams:['آزمون‌ها','Exams'],culture:['فرهنگ و زبان','Culture']};
const teacherEnglish={'sample-sara':['Sara Mehr','Conversation that starts with everyday life'], 'sample-arman':['Arman Rad','Step by step to speaking German'],'sample-leila':['Leila Navid','French beyond the words']};
const titleTeacher=x=>prefs.lang==='en'?(x.nameEn||teacherEnglish[x.id]?.[0]||x.name):x.name;
const headlineTeacher=x=>prefs.lang==='en'?(teacherEnglish[x.id]?.[1]||'Language teacher'):x.headline;
const titleStudent=x=>prefs.lang==='en'?(x.nameEn||x.name):x.name;
const icons={book:'M4 19.5A2.5 2.5 0 0 1 6.5 17H20 M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2Z',arrow:'M7 17 17 7M7 7h10v10',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8M22 21v-2a4 4 0 0 0-3-3.87 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',search:'m21 21-4.3-4.3M19 11a8 8 0 1 1-16 0 8 8 0 0 1 16 0',globe:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M3 12h18M12 3a18 18 0 0 1 0 18 18 18 0 0 1 0-18',video:'m16 8 6-3v14l-6-3 M2 6h14v12H2Z',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0M12 7v5l3 2',message:'M21 11.5a8.4 8.4 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.4 8.4 0 0 1-3.8-.9L3 21l1.9-5.7a8.4 8.4 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.4 8.4 0 0 1 3.8-.9h.5a8.5 8.5 0 0 1 8 8Z',sun:'M12 3v2M12 19v2M3 12h2M19 12h2M5.6 5.6 7 7M17 17l1.4 1.4M5.6 18.4 7 17M17 7l1.4-1.4M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',moon:'M21 12.8A9 9 0 1 1 11.2 3 7 7 0 0 0 21 12.8',plus:'M12 5v14M5 12h14',calendar:'M8 2v4M16 2v4M3 10h18M3 4h18v18H3Z',wallet:'M20 8V4H4v16h16V8ZM16 12h6v4h-6Z',check:'m5 12 4 4L19 6',settings:'M12 8a4 4 0 1 1 0 8 4 4 0 0 1 0-8M12 2v3M12 19v3M2 12h3M19 12h3M5 5l2 2M17 17l2 2M5 19l2-2M17 7l2-2',grid:'M3 3h7v7H3ZM14 3h7v7h-7ZM3 14h7v7H3ZM14 14h7v7h-7Z',menu:'M4 6h16M4 12h16M4 18h16',close:'m6 6 12 12M6 18 18 6',up:'m6 12 6-6 6 6M12 6v14',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',edit:'m16 3 5 5-13 13H3v-5Z',mail:'M3 5h18v14H3Zm0 0 9 7 9-7',shield:'M12 2 3 6v6c0 5 9 10 9 10s9-5 9-10V6Z'};
function icon(name,size=20){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`}
const link=(url,text,cls='')=>`<a href="${esc(url)}" class="${cls}">${text}</a>`;
const button=(action,text,cls='btn',attrs='')=>`<button type="button" class="${cls}" data-action="${action}" ${attrs}>${text}</button>`;
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),4500)}
function save(){const ok=persistState(storage,state);if(!ok)toast(t('ذخیره در مرورگر ممکن نشد؛ تغییرات فقط تا بستن صفحه باقی می‌ماند.','Browser storage is unavailable; changes last only for this visit.'));return ok}
function demoBar(){return `<aside class="demo-bar"><span>${icon('shield',16)}${t('نسخه نمایشی · همه اطلاعات نمونه‌اند؛ چیزی برای مدیریت ارسال نمی‌شود.','Demo · All data is sample data. Nothing is sent to the administrator.')}</span><div>${link('/signin',t('دیدن پنل‌ها','Explore dashboards'))}${button('reset',t('بازنشانی دمو','Reset demo'),'demo-reset')}</div></aside>`}
function header(active='home'){return `<header class="pub-header"><div class="pub-container pub-header-inner">${link('/',`<span class="brand-mark pub-mark">${icon('book',24)}</span><span dir="ltr">Class<b>er</b><i>.</i></span>`,'pub-logo')}<nav class="pub-nav" aria-label="${t('منوی اصلی','Main navigation')}">${[['/','خانه','Home','home'],['/teachers','معلم‌ها','Teachers','teachers'],['/blog','بلاگ','Journal','blog'],['/contact','ارتباط با ما','Contact','contact']].map(([url,fa,en,key])=>link(url,t(fa,en),key===active?'active':'')).join('')}</nav><div class="pub-header-actions">${button('theme',icon(prefs.dark?'sun':'moon'),'icon-button',`aria-label="${t('تغییر تم','Toggle theme')}"`)}${button('language',icon('globe',16)+(prefs.lang==='fa'?'EN':'فا'),'pub-language')}${link('/signin',t('ورود به حساب','Sign in'),'btn primary pub-teacher-login')}${button('menu',icon('menu'),'icon-button pub-mobile-menu',`aria-label="${t('باز کردن منو','Open menu')}"`)}</div></div></header>`}
function footer(){return `<footer class="pub-footer"><div class="pub-container demo-footer"><div><b dir="ltr">Classer.</b><p>${t('فضای رشد و یادگیری','A space for learning and growth')}</p></div><span>${t('نمونهٔ تعاملی؛ بدون حساب و پرداخت واقعی','Interactive demo · No real accounts or payments')}</span>${link('/signin',t('امتحان کردن پنل معلم','Try the teacher dashboard'),'text-link')}</div></footer>${button('top',icon('up')+`<span>${t('بالای صفحه','Back to top')}</span>`,'pub-back-top',`aria-label="${t('بازگشت به بالای صفحه','Back to top')}"`)}`}
function sectionHeading(kicker,title,description,action=''){return `<div class="section-heading"><div><span class="pub-kicker">${kicker}</span><h2>${title}</h2><p>${description}</p></div>${action}</div>`}
function face(person,large=false){return `<span class="pub-face ${large?'large':''}" aria-hidden="true">${esc(titleTeacher(person).split(' ').slice(0,2).map(v=>v[0]).join(' '))}</span>`}
function teacherCard(x){return `<article class="teacher-tile"><div class="teacher-tile-head">${face(x)}<div><span class="pub-kicker">${x.languages.map(k=>t(...langs[k])).join(' · ')}</span><h3>${link('/teachers/'+x.id,esc(titleTeacher(x)))}</h3></div><span class="sample-pill">${t('نمونه','Sample')}</span></div><p class="teacher-tagline">${esc(headlineTeacher(x))}</p><div class="teacher-facts"><span>${icon('users')}${n(x.experience)} ${t('سال تجربه تدریس','years teaching')}</span><span>${icon(x.formats.includes('online')?'video':'pin')}${x.formats.length===2?t('آنلاین و حضوری','Online & in person'):t('آنلاین','Online')}</span></div><div class="teacher-topics">${(prefs.lang==='fa'?x.specialties.split('،'):['Conversation','Personal learning plan']).map(s=>`<span>${esc(s)}</span>`).join('')}</div><div class="teacher-price"><div><strong>${money(x.rate,x.currency)}</strong><small>${t('هر جلسه','per class')} · ${n(x.duration)} ${t('دقیقه','min')}</small></div>${link('/teachers/'+x.id,icon('arrow'),'pub-circle-link')}</div></article>`}
const articleEnglish=['Small steps every day: build a language habit','Three questions to ask before your first speaking class','Online or in person: which class fits your life?'];
function articleTitle(x){return prefs.lang==='fa'?x.title:(x.titleEn||articleEnglish[seed.articles.findIndex(a=>a.id===x.id)]||x.title)}
function blogCard(x,i=0){const teacher=state.teachers.find(a=>a.id===x.teacherId);return `<article class="blog-tile blog-tone-${i%3}">${link('/blog/'+x.id,`<span class="pub-kicker">${t(...(categories[x.category]||categories.learning))}</span><h3>${esc(articleTitle(x))}</h3><span class="blog-cover-bottom">${icon('book',24)}${icon('arrow',24)}</span>`,'blog-cover')}<div class="blog-tile-copy"><p>${esc(t(x.excerpt,'Practical ideas, small exercises and fresh perspectives for your next learning step.'))}</p><div class="blog-byline">${teacher?face(teacher)+link('/teachers/'+teacher.id,esc(titleTeacher(teacher))):''}<span>${n(4)} ${t('دقیقه مطالعه','min read')}</span></div></div></article>`}
function discovery(){return `<form id="discovery" class="demo-discovery"><label>${t('می‌خواهی چه زبانی یاد بگیری؟','What would you like to learn?')}<select name="language">${options([['all',t('همه زبان‌ها','All languages')],...Object.entries(langs).map(([k,v])=>[k,t(...v)])],filters.language)}</select></label><label>${t('نوع کلاس','Class format')}<select name="format">${options([['all',t('آنلاین یا حضوری','Online or in person')],['online',t('آنلاین','Online')],['in-person',t('حضوری','In person')]],filters.format)}</select></label><button class="btn primary">${icon('search')}${t('جستجوی معلم','Find a teacher')}</button></form>`}
function home(){return `<main class="classer-home"><section class="home-stage"><div class="pub-container home-stage-inner"><div class="home-copy"><div class="home-eyebrow"><span></span><bdi>CLASSER</bdi><i></i>${t('فضای یادگیری زبان','A SPACE TO LEARN LANGUAGES')}</div><h1>${t('زبان تازه،','A new language.')}<br><em>${t('با معلمی که به تو می‌خورد.','A teacher who fits.')}</em></h1><p>${t('از مکالمهٔ روزمره تا آمادگی آزمون؛ معلم‌ها را بر اساس زبان، نوع کلاس و بودجه مقایسه کن و برای شروع درخواست بده.','From everyday conversation to exam prep, compare teachers by language, class format and budget, then request a class.')}</p><div class="home-links">${link('/teachers',t('دیدن معلم‌ها','Explore teachers')+icon('arrow'),'home-main-link')}${link('/blog',icon('book')+t('بلاگ معلم‌ها','Teachers’ journal'),'home-journal-link')}</div></div><figure class="home-figure"><img src="/images/learning-hero.webp" alt="${t('تصویر معلم در فضای آموزش آنلاین','Illustration of a teacher in an online learning space')}" width="1122" height="1402" fetchpriority="high"><div class="home-language-chip" dir="ltr">${icon('globe')} Hello · Bonjour · Hallo</div><figcaption><span class="home-caption-icon">${icon('message')}</span><div><strong>${t('همه‌چیز از یک سلام شروع می‌شود.','It all starts with hello.')}</strong><span>${t('آنلاین یا حضوری، به انتخاب تو','Online or in person, your choice')}</span></div></figcaption></figure><div class="home-discovery">${discovery()}</div></div></section><section class="home-steps pub-container"><div class="home-steps-title"><span class="pub-kicker">${t('از کجا شروع کنم؟','HOW IT WORKS')}</span><h2>${t('تا کلاس اول، سه قدم.','Three steps to your first class.')}</h2></div><ol class="home-step-list">${[['search','زبان و نوع کلاس را انتخاب کن','Choose a language and format','آنلاین یا حضوری؛ گزینه‌هایی را ببین که به برنامه‌ات می‌خورند.','Find options that fit your schedule.'],['users','با معلم‌ها آشنا شو','Get to know the teachers','رزومه، شیوهٔ تدریس و هزینهٔ هر جلسه را مقایسه کن.','Compare experience, teaching style and class fees.'],['message','درخواست کلاس بده','Request a class','فرم درخواست را در این نسخه به‌صورت نمایشی امتحان کن.','Try the sample class request form.']].map(([ic,fa,en,fd,ed],i)=>`<li class="home-step"><div class="home-step-top"><span class="home-step-icon">${icon(ic)}</span><span class="home-step-number">${n(i+1)}</span></div><h3>${t(fa,en)}</h3><p>${t(fd,ed)}</p></li>`).join('')}</ol></section><section class="pub-section pub-container">${sectionHeading(t('آدم‌های پشت یادگیری','PEOPLE BEHIND THE LEARNING'),t('همراه بعدی مسیر تو','Your next learning partner'),t('با روش تدریس، تجربه و هزینه کلاس هر معلم آشنا شو.','Get to know each teacher’s approach, experience and class fees.'),link('/teachers',t('همه معلم‌ها','All teachers')+icon('arrow'),'pub-quiet-link'))}<div class="teacher-tiles">${state.teachers.map(teacherCard).join('')}</div></section><section class="pub-journal-section"><div class="pub-container">${sectionHeading(t('یادگیری، بیرون از کلاس','LEARNING BEYOND THE CLASSROOM'),t('از دفتر معلم‌ها','From our teachers’ notebooks'),t('تجربه‌ها و تمرین‌هایی برای یک قدم جلوتر رفتن.','Ideas and exercises to take your learning further.'),link('/blog',t('ورق زدن بلاگ','Explore the journal'),'pub-quiet-link'))}<div class="blog-tiles">${state.articles.filter(x=>x.status==='published').slice(0,3).map(blogCard).join('')}</div></div></section><div class="pub-container pub-contact-banner"><div><span class="pub-kicker">${t('با هم، مسیر مناسب را پیدا می‌کنیم','LET’S FIND YOUR WAY FORWARD')}</span><h2>${t('برای انتخاب معلم کمک می‌خواهی؟','Need a hand choosing a teacher?')}</h2></div>${link('/contact',t('ارتباط با مدیریت','Contact the administrator')+icon('arrow'),'btn pub-white-btn')}</div></main>`}
function intro(kicker,title,description){return `<div class="demo-intro"><span class="pub-kicker">${kicker}</span><h1>${title}</h1><p>${description}</p></div>`}
function matchingTeachers(){return state.teachers.filter(x=>(filters.language==='all'||x.languages.includes(filters.language))&&(filters.format==='all'||x.formats.includes(filters.format))&&(!filters.query||(titleTeacher(x)+' '+x.headline+' '+x.specialties).toLowerCase().includes(filters.query.toLowerCase())))}
function directory(){return `<main class="pub-container pub-inner-page">${intro(t('معلم‌ها را بشناس','MEET YOUR TEACHER'),t('یادگیری خوب، با یک انتخاب خوب.','Great learning starts with a great fit.'),t('زبان، نوع کلاس و بودجه‌ات را انتخاب کن.','Choose your language and class format.'))}${discovery()}<div class="filters"><div class="search-field">${icon('search')}<input id="teacher-search" type="search" aria-label="${t('جستجوی معلم','Search teachers')}" placeholder="${t('جستجوی نام یا تخصص…','Search name or specialty…')}" value="${esc(filters.query)}"></div><span id="teacher-count">${n(matchingTeachers().length)} ${t('معلم نمونه','sample teachers')}</span></div><div class="teacher-tiles" id="teacher-results">${matchingTeachers().map(teacherCard).join('')||empty(t('معلمی با این فیلتر پیدا نشد.','No teacher matches these filters.'))}</div></main>`}
function teacherPage(id){const x=state.teachers.find(v=>v.id===id);if(!x)return notFound();return `<main class="pub-container pub-inner-page">${link('/teachers',t('بازگشت به معلم‌ها','Back to teachers'),'pub-back')}<div class="demo-portfolio"><div><section class="panel demo-profile">${face(x,true)}<span class="sample-pill">${t('پروفایل نمونه','Sample profile')}</span><h1>${esc(titleTeacher(x))}</h1><h2>${esc(headlineTeacher(x))}</h2><div class="teacher-topics">${x.languages.map(k=>`<span>${t(...langs[k])}</span>`).join('')}</div><p>${esc(t(x.bio,'This is a sample teacher profile showing the teaching approach, class formats and fees. Lessons can be tailored to each learner’s level and goals.'))}</p></section><section class="panel demo-profile"><h2>${t('تجربه و روش تدریس','Experience & teaching approach')}</h2><p>${n(x.experience)} ${t('سال تجربه تدریس · تمرین کاربردی، مکالمه و بازخورد منظم','years teaching · Practical exercises, conversation and regular feedback')}</p><div class="teacher-topics">${(prefs.lang==='fa'?x.specialties.split('،'):['Conversation','Pronunciation','Individual learning']).map(s=>`<span>${esc(s)}</span>`).join('')}</div></section></div><aside class="panel demo-booking"><span class="pub-kicker">${t('کلاس‌های این معلم','AVAILABLE CLASSES')}</span><h2>${t('یک قدم تا شروع','One step from starting')}</h2>${x.languages.flatMap(k=>x.formats.map(f=>`<div class="demo-offer"><strong>${t(...langs[k])} · ${f==='online'?t('آنلاین','Online'):t('حضوری','In person')}</strong><span>${money(x.rate,x.currency)} · ${n(x.duration)} ${t('دقیقه','min')}</span></div>`)).join('')}${button('request',t('درخواست کلاس نمونه','Try a class request')+icon('arrow'),'btn primary',`data-id="${esc(x.id)}"`)}<small>${t('این فرم نمایشی است؛ هیچ درخواستی ارسال نمی‌شود.','Demo form. No request will be sent.')}</small></aside></div><section class="pub-section">${sectionHeading(t('دفتر معلم','TEACHER’S NOTEBOOK'),t('نوشته‌های آموزشی','Learning notes'),'')}<div class="blog-tiles">${state.articles.filter(a=>a.teacherId===x.id&&a.status==='published').map(blogCard).join('')}</div></section></main>`}
function journal(){return `<main class="pub-container pub-inner-page">${intro(t('مجلهٔ زبان','LANGUAGE JOURNAL'),t('کلمه به کلمه، جلوتر.','Word by word, a little further.'),t('تجربه، تمرین و راه‌های تازه یادگیری.','Practice, perspective and new ways to learn.'))}<div class="demo-pills">${[['all',t('همه نوشته‌ها','All posts')],...Object.entries(categories).map(([k,v])=>[k,t(...v)])].map(([k,v])=>button('category',v,'btn '+((query.get('category')||'all')===k?'primary':''),`data-id="${k}"`)).join('')}</div><div class="blog-tiles">${state.articles.filter(a=>a.status==='published'&&(!query.get('category')||query.get('category')===a.category)).map(blogCard).join('')||empty(t('در این دسته هنوز نوشته‌ای نیست.','No posts in this category yet.'))}</div></main>`}
function articlePage(id){const x=state.articles.find(a=>a.id===id&&a.status==='published');if(!x)return notFound();const teacher=state.teachers.find(a=>a.id===x.teacherId);return `<main class="pub-container pub-inner-page"><article class="demo-article">${link('/blog',t('بازگشت به بلاگ','Back to journal'),'pub-back')}<span class="pub-kicker">${t(...(categories[x.category]||categories.learning))}</span><h1>${esc(articleTitle(x))}</h1><div class="blog-byline">${teacher?face(teacher)+esc(titleTeacher(teacher)):''}<span>${date(x.createdAt.slice(0,10))}</span></div><div class="demo-prose">${prose(t(x.content,'Choose a small activity you can repeat even on a busy day. Write a few sentences, listen to a short recording, or practise a useful conversation.\n\n## Start with a real situation\nThink of something you want to say in your new language. Gather a few useful phrases and practise them aloud.\n\n## Make practice repeatable\nConnect your practice to something you already do each day. A small, consistent step is easier to sustain.\n\n## Ask for feedback\nBring your practice to your teacher. Together you can find recurring mistakes and set a useful goal for the next lesson.'))}</div></article></main>`}
function prose(text){return String(text).split(/\n\n+/).map(p=>p.startsWith('## ')?`<h2>${esc(p.slice(3))}</h2>`:`<p>${esc(p).replace(/\n/g,'<br>')}</p>`).join('')}
function contact(){return `<main class="pub-container pub-inner-page"><div class="contact-page-grid"><div class="contact-page-copy"><span class="pub-kicker">${t('شروع یک گفت‌وگو','START A CONVERSATION')}</span><h1>${t('از اینجا،','It starts')}<br><em>${t('با هم شروع کنیم.','with a conversation.')}</em></h1><p>${t('فرم ارتباط با مدیریت را امتحان کن. در این نسخه پیام فقط در مرورگر خودت ذخیره می‌شود.','Try the contact form. In this demo your message stays in your browser.')}</p></div><section class="panel demo-profile">${inquiryForm()}</section></div></main>`}
function field(label,name,value='',type='text',extra=''){return `<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${extra}></label>`}
function options(items,selected){return items.map(([v,l])=>`<option value="${esc(v)}" ${v===selected?'selected':''}>${esc(l)}</option>`).join('')}
function inquiryForm(teacher){return `<form data-form="inquiry" data-id="${esc(teacher?.id||'')}" class="demo-form"><div class="demo-form-notice">${t('فرم نمونه؛ اطلاعات واقعی وارد نکنید. پیامی ارسال نمی‌شود.','Sample form. Use sample details. No message will be sent.')}</div>${field(t('نام','Name'),'name','', 'text','required minlength="2" maxlength="100"')}${field(t('ایمیل نمونه','Sample email'),'email','', 'email','required maxlength="200"')}${teacher?`<label class="field">${t('نوع کلاس','Class format')}<select name="format">${options(teacher.formats.map(f=>[f,f==='online'?t('آنلاین','Online'):t('حضوری','In person')]))}</select></label>`:''}<label class="field">${t('پیام','Message')}<textarea name="message" required minlength="5" maxlength="2000" rows="4"></textarea></label><button class="btn primary">${t('ثبت درخواست نمونه','Save sample request')}${icon('arrow')}</button></form>`}
function signin(){return `<main class="pub-container pub-inner-page">${intro('CLASSER DEMO',t('از هر زاویه، Classer را ببین.','Explore every side of Classer.'),t('بدون ثبت‌نام یا رمز، وارد پنل نمونه شو.','Explore a sample dashboard without an account or password.'))}<div class="demo-roles">${[['/dashboard','users','پنل معلم','Teacher dashboard','برنامه کلاس‌ها، زبان‌آموزان، شهریه و یادداشت‌ها','Classes, students, fees and notes'],['/student','book','پنل زبان‌آموز','Student dashboard','کلاس‌های پیش رو و مسیر پیشرفت','Upcoming classes and learning progress'],['/admin','shield','پنل مدیر','Admin dashboard','نمای کلی معلم‌ها و درخواست‌های نمونه','Teachers and sample requests']].map(([url,ic,fa,en,fd,ed])=>`<article class="panel demo-role"><span class="demo-role-icon">${icon(ic,32)}</span><h2>${t(fa,en)}</h2><p>${t(fd,ed)}</p>${link(url,t('دیدن پنل','Explore dashboard')+icon('arrow'),'btn primary')}</article>`).join('')}</div></main>`}
function empty(text){return `<div class="demo-empty">${icon('book',30)}<p>${text}</p></div>`}
function notFound(){return `<main class="pub-container pub-inner-page">${intro('404',t('صفحه پیدا نشد.','Page not found.'),'')}${link('/',t('بازگشت به خانه','Back home'),'btn primary')}</main>`}

const workspaceRoutes=['dashboard','students','schedule','finance','messages','studio','journal','admin','student'];
const navItems=[['dashboard','grid','پیشخوان','Overview'],['students','users','زبان‌آموزان','Students'],['schedule','calendar','برنامه کلاس‌ها','Schedule'],['finance','wallet','شهریه و تسویه','Finance'],['messages','message','گفتگوها','Messages'],['studio','settings','تنظیمات کلاس و پروفایل','Class & profile'],['journal','book','بلاگ من','My journal']];
function workspaceShell(view,content){const profile=prefs.lang==='fa'?state.profile.name:state.profile.nameEn;return `<div class="demo-workspace"><aside class="demo-sidebar">${link('/',`<span class="brand-mark">${icon('book',24)}</span><div><strong dir="ltr">Classer.</strong><small>${t('فضای رشد و یادگیری','A SPACE FOR LEARNING')}</small></div>`,'brand')}<div class="nav-label">${t('فضای کار نمونه','DEMO WORKSPACE')}</div><nav aria-label="${t('پنل معلم','Teacher navigation')}">${navItems.map(([key,ic,fa,en])=>link('/'+key,icon(ic)+`<span>${t(fa,en)}</span>`,view===key?'active':'')).join('')}</nav><div class="demo-sidebar-bottom">${link('/signin',t('تغییر پنل نمونه','Switch demo dashboard'),'btn')}${link('/',t('بازگشت به سایت','Back to website'),'text-link')}<small>${esc(profile)}</small></div></aside><div class="demo-workspace-body"><header class="topbar"><div class="crumb">${button('workspace-menu',icon('menu'),'icon-button demo-workspace-menu',`aria-label="${t('منوی پنل','Dashboard menu')}"`)}<span>${t('فضای کار نمونه','Demo workspace')}</span><strong>${t(navItems.find(x=>x[0]===view)?.[2]||'پنل',navItems.find(x=>x[0]===view)?.[3]||'Dashboard')}</strong></div><div class="top-actions">${button('theme',icon(prefs.dark?'sun':'moon'),'icon-button',`aria-label="${t('تغییر تم','Toggle theme')}"`)}${button('language',prefs.lang==='fa'?'EN':'فا','icon-button')}${link('/studio',`<span class="avatar">${esc(profile?.[0]||'م')}</span>`)}</div></header><main class="main-content">${content}</main></div></div>`}
function pageHeading(title,description,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${description}</p></div><div class="actions">${action}</div></div>`}
function metric(label,value,foot,ic,emphasis=false){return `<div class="metric ${emphasis?'emphasis':''}"><div class="metric-top"><span>${label}</span><span class="metric-icon">${icon(ic)}</span></div><div class="metric-number">${value}</div><div class="metric-bottom">${foot}</div></div>`}
function sessionList(sessions){return sessions.length?sessions.slice().sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).map(s=>{const st=state.students.find(x=>x.id===s.studentId);return `<div class="session-row session-status-${s.status}"><div class="session-time"><span>${esc(s.time)}</span><small>${n(s.duration)} ${t('دقیقه','min')}</small></div><div class="session-line"></div><span class="avatar">${esc(titleStudent(st||{name:'؟'})[0])}</span><div class="session-info"><strong>${esc(st?titleStudent(st):t('زبان‌آموز حذف‌شده','Removed student'))}</strong><p>${date(s.date)} · ${s.type==='online'?t('آنلاین','Online'):t('حضوری','In person')}</p></div><span class="badge ${s.status==='cancelled'?'gray':s.status==='scheduled'?'purple':''}">${statusLabel(s.status)}</span>${button('edit-session',icon('edit',16),'icon-button',`data-id="${esc(s.id)}" aria-label="${t('جزئیات جلسه','Class details')}"`)}</div>`}).join(''):empty(t('برای این روز کلاسی نیست.','No classes on this day.'))}
function statusLabel(status){return status==='held'?t('برگزار شده','Completed'):status==='cancelled'?t('لغو شده','Cancelled'):t('برنامه‌ریزی شده','Scheduled')}
function roster(){return `<div class="demo-table-wrap"><table class="roster-table"><thead><tr><th>${t('زبان‌آموز','Student')}</th><th>${t('سطح','Level')}</th><th>${t('شهریه جلسه','Class fee')}</th><th>${t('پرونده','Profile')}</th></tr></thead><tbody>${state.students.map(s=>`<tr><td>${link('/students/'+s.id,`<span class="avatar">${esc(titleStudent(s)[0])}</span><strong>${esc(titleStudent(s))}</strong>`,'student-cell')}</td><td><span class="badge">${esc(s.level)}</span></td><td>${money(s.rate,s.currency)}</td><td>${link('/students/'+s.id,icon('arrow'),'icon-button')}</td></tr>`).join('')}</tbody></table></div>`}
function dashboard(){const today=tehranDay(),upcoming=state.sessions.filter(s=>s.date>=today&&s.status==='scheduled'),unpaid=state.sessions.filter(s=>s.status==='held'&&!s.paid);return pageHeading(t('روز بخیر، '+state.profile.name+'!','Hello, '+state.profile.nameEn+'!'),t('امروز، یک قدم نزدیک‌تر به پیشرفت زبان‌آموزانتان.','A little more progress for every learner, every day.'),button('add-student',icon('users')+t('افزودن زبان‌آموز','Add student'))+button('add-session',icon('plus')+t('کلاس جدید','New class'),'btn primary'))+`<div class="welcome-strip">${icon('shield')}<span>${t('امکانات را امتحان کنید؛ تغییرات فقط در همین مرورگر ذخیره می‌شوند.','Try the features. Changes are stored only in this browser.')}</span></div><div class="metrics">${metric(t('زبان‌آموزان فعال','Active students'),n(state.students.length),t('در مسیر یادگیری با شما','Learning with you'),'users')}${metric(t('کلاس‌های پیش رو','Upcoming classes'),n(upcoming.length),t('برنامه‌ریزی شده','Scheduled'),'calendar')}${metric(t('زمان آموزش','Teaching time'),n(upcoming.reduce((a,s)=>a+s.duration,0)/60),t('ساعت برنامه‌ریزی شده','Hours scheduled'),'clock')}${metric(t('جلسات تسویه‌نشده','Unpaid classes'),n(unpaid.length),t('تسویه نمایشی','Sample settlements'),'wallet',true)}</div><section class="panel demo-profile"><div class="panel-head demo-panel-head"><h2>${t('تابلوی یادداشت','Memo board')}</h2>${button('add-memo',icon('plus')+t('یادداشت جدید','New note'),'btn compact')}</div><div class="demo-memos">${state.memos.map(m=>`<article class="demo-memo ${esc(m.color)}"><h3>${esc(m.title)}</h3><p>${esc(m.body)}</p><div>${button('edit-memo',icon('edit',16),'icon-button',`data-id="${esc(m.id)}" aria-label="${t('ویرایش یادداشت','Edit note')}"`)}${button('delete-memo',icon('trash',16),'icon-button',`data-id="${esc(m.id)}" aria-label="${t('حذف یادداشت','Delete note')}"`)}</div></article>`).join('')}</div></section><div class="overview-grid"><section class="panel"><div class="panel-head"><h2>${t('برنامه امروز','Today’s schedule')}</h2>${link('/schedule',t('تقویم کامل','Full schedule'),'text-link')}</div><div class="schedule-list">${sessionList(state.sessions.filter(s=>s.date===today))}</div></section><section class="panel"><div class="panel-head"><h2>${t('زبان‌آموزان شما','Your students')}</h2></div>${roster()}</section></div>`}
function students(id){if(id){const s=state.students.find(x=>x.id===id);if(!s)return empty(t('پرونده پیدا نشد.','Student not found.'));return pageHeading(esc(titleStudent(s)),esc(s.email),button('edit-student',t('ویرایش پرونده','Edit profile'),'btn',`data-id="${esc(s.id)}"`))+`<div class="stats-three">${metric(t('سطح زبان','Language level'),esc(s.level),t('انگلیسی','English'),'book')}${metric(t('شهریه جلسه','Class fee'),money(s.rate,s.currency),n(s.duration)+' '+t('دقیقه','minutes'),'wallet')}${metric(t('جلسات','Classes'),n(state.sessions.filter(x=>x.studentId===id).length),t('جلسات ثبت‌شده','Recorded classes'),'calendar')}</div><section class="panel"><div class="panel-head"><h2>${t('برنامه و سوابق','Schedule & history')}</h2></div><div class="schedule-list">${sessionList(state.sessions.filter(x=>x.studentId===id))}</div></section>`}return pageHeading(t('زبان‌آموزان شما','Your students'),t('هر زبان‌آموز، یک مسیر منحصربه‌فرد.','A unique learning journey for every student.'),button('add-student',icon('plus')+t('افزودن زبان‌آموز','Add student'),'btn primary'))+`<section class="panel">${state.students.length?roster():empty(t('اولین زبان‌آموز نمونه را اضافه کن.','Add your first sample student.'))}</section>`}
function schedule(){return pageHeading(t('برنامه کلاس‌ها','Class schedule'),t('جلسه‌ها را ببین، اضافه کن و وضعیتشان را تغییر بده.','View classes, add new ones and update their status.'),button('add-session',icon('plus')+t('کلاس جدید','New class'),'btn primary'))+`<section class="panel demo-profile"><div class="demo-calendar-controls">${button('previous-day','→','btn',`aria-label="${t('روز قبل','Previous day')}"`)}<label>${t('تاریخ','Date')} <input type="date" id="schedule-day" value="${selectedDay}"></label>${button('next-day','←','btn',`aria-label="${t('روز بعد','Next day')}"`)}${button('today',t('امروز','Today'),'btn')}</div><h2>${date(selectedDay,{weekday:'long',day:'numeric',month:'long',year:'numeric'})}</h2><div class="schedule-list">${sessionList(state.sessions.filter(s=>s.date===selectedDay))}</div></section><section class="panel"><div class="panel-head"><h2>${t('همه کلاس‌ها','All classes')}</h2></div><div class="schedule-list">${sessionList(state.sessions)}</div></section>`}
function finance(){const held=state.sessions.filter(s=>s.status==='held');return pageHeading(t('شهریه و تسویه','Fees & settlement'),t('مبالغ و تسویه‌ها در این پنل صرفاً نمایشی‌اند.','Fees and settlements here are demonstrations only.'))+`<div class="metrics">${['TOMAN','USD'].map(c=>metric(t('مجموع تسویه‌نشده','Outstanding total'),money(held.filter(s=>!s.paid&&s.currency===c).reduce((a,s)=>a+s.rate,0),c),t('جلسات برگزارشده','Completed classes'),'wallet')).join('')}</div><section class="panel demo-table-wrap"><table class="roster-table"><thead><tr><th>${t('زبان‌آموز','Student')}</th><th>${t('تاریخ','Date')}</th><th>${t('مبلغ','Amount')}</th><th>${t('وضعیت','Status')}</th></tr></thead><tbody>${held.map(s=>`<tr><td>${esc(titleStudent(state.students.find(x=>x.id===s.studentId)||{name:'—'}))}</td><td>${date(s.date)}</td><td>${money(s.rate,s.currency)}</td><td>${s.paid?`<span class="badge">${t('تسویه شده','Settled')}</span>`:button('settle',t('تسویه نمونه','Sample settlement'),'btn compact',`data-id="${esc(s.id)}"`)}</td></tr>`).join('')}</tbody></table></section>`}
function memForm(m){return `<form data-form="memo" data-id="${esc(m?.id||'')}" class="demo-form">${field(t('عنوان','Title'),'title',m?.title||'','text','required maxlength="120"')}<label class="field">${t('متن یادداشت','Note')}<textarea name="body" rows="5" required maxlength="2000">${esc(m?.body||'')}</textarea></label><label class="field">${t('رنگ','Color')}<select name="color">${options([['mint',t('نعنایی','Mint')],['amber',t('کهربایی','Amber')],['lilac',t('یاسی','Lilac')]],m?.color||'mint')}</select></label><button class="btn primary">${t('ذخیره در دمو','Save in demo')}</button></form>`}
function messages(){const selected=query.get('student')||state.students[0]?.id,student=state.students.find(s=>s.id===selected);return pageHeading(t('گفتگوها','Messages'),t('پیام‌ها فقط در مرورگر ذخیره می‌شوند؛ مخاطب واقعی ندارند.','Messages stay in your browser and have no real recipient.'))+`<div class="panel messages-layout"><aside class="conversation-list">${state.students.map(s=>link('/messages?student='+s.id,`<span class="avatar">${esc(titleStudent(s)[0])}</span><strong>${esc(titleStudent(s))}</strong>`,'conversation-item '+(selected===s.id?'selected':''))).join('')}</aside><div class="conversation-body"><div class="demo-chat">${state.messages.filter(m=>m.studentId===selected).map(m=>`<div class="chat-message ${m.direction==='out'?'demo-out':''}">${esc(m.text)}</div>`).join('')}</div>${student?`<form data-form="message" data-id="${esc(selected)}" class="message-form"><textarea name="text" required maxlength="2000" aria-label="${t('پیام نمونه','Sample message')}" placeholder="${t('پیام نمونه بنویس…','Write a sample message…')}"></textarea><button class="btn primary">${t('ثبت پیام نمونه','Save sample message')}</button></form>`:empty(t('ابتدا زبان‌آموز اضافه کن.','Add a student first.'))}</div></div>`}
function studio(){return pageHeading(t('تنظیمات کلاس و پروفایل','Class & profile settings'),t('این تغییرات فقط در نسخه نمایشی همین مرورگر ذخیره می‌شوند.','These changes are saved only in this browser’s demo.'))+`<section class="panel demo-profile"><form data-form="profile" class="demo-form"><div class="form-grid">${field(t('نام فارسی','Persian name'),'name',state.profile.name,'text','required maxlength="100"')}${field(t('نام انگلیسی','English name'),'nameEn',state.profile.nameEn,'text','required maxlength="100"')}${field(t('ایمیل نمونه','Sample email'),'email',state.profile.email,'email','required')}${field(t('عنوان تدریس','Teaching title'),'headline',state.profile.headline,'text','required maxlength="150"')}</div><label class="field">${t('درباره من','About me')}<textarea name="bio" rows="5" maxlength="1500">${esc(state.profile.bio)}</textarea></label><button class="btn primary">${t('ذخیره پروفایل نمونه','Save sample profile')}</button></form></section><section class="panel demo-profile"><h2>${t('رنگ اصلی سایت','Primary site color')}</h2><p>${t('تغییر رنگ را در همین نمونه امتحان کن.','Try a new accent color for this demo.')}</p><input id="accent-color" type="color" value="${/^#[a-f\d]{6}$/i.test(prefs.accent||'')?prefs.accent:'#147d67'}" aria-label="${t('رنگ اصلی','Primary color')}"></section>`}
function teacherJournal(){return pageHeading(t('بلاگ من','My journal'),t('یک نوشته نمونه اضافه کن و آن را در بلاگ عمومی ببین.','Add a sample post and view it in the public journal.'),button('add-article',icon('plus')+t('نوشته جدید','New post'),'btn primary'))+`<div class="blog-tiles">${state.articles.filter(a=>a.teacherId==='sample-sara').map((a,i)=>`<div>${blogCard(a,i)}<div class="demo-post-actions"><span class="badge">${a.status==='published'?t('منتشر شده','Published'):t('پیش‌نویس','Draft')}</span>${button('edit-article',icon('edit',16)+t('ویرایش','Edit'),'btn compact',`data-id="${esc(a.id)}"`)}${button('delete-article',icon('trash',16),'icon-button',`data-id="${esc(a.id)}" aria-label="${t('حذف مقاله','Delete post')}"`)}</div></div>`).join('')}</div>`}
function admin(){return pageHeading(t('پیشخوان مدیر','Admin overview'),t('همه کاربران و درخواست‌های این صفحه نمونه‌اند.','All users and requests on this page are sample data.'))+`<div class="metrics">${metric(t('معلم‌ها','Teachers'),n(state.teachers.length),t('پروفایل نمونه','Sample profiles'),'users')}${metric(t('زبان‌آموزان','Students'),n(state.students.length),t('پرونده نمونه','Sample records'),'book')}${metric(t('درخواست‌ها','Requests'),n(state.requests.length),t('ثبت‌شده در همین مرورگر','Saved in this browser'),'message')}</div><section class="panel"><div class="panel-head"><h2>${t('معلم‌ها','Teachers')}</h2></div><div class="demo-admin-teachers">${state.teachers.map(x=>`<div>${face(x)}<strong>${esc(titleTeacher(x))}</strong><span class="badge">${t('فعال · نمونه','Active · Sample')}</span>${link('/teachers/'+x.id,t('پروفایل','Profile'),'btn compact')}</div>`).join('')}</div></section><section class="panel demo-profile"><h2>${t('درخواست‌های نمونه','Sample requests')}</h2>${state.requests.length?state.requests.map(r=>`<article class="demo-request"><strong>${esc(r.name)}</strong><small>${esc(r.email)}</small><p>${esc(r.message)}</p><span class="badge">${t('فقط در این مرورگر','Only in this browser')}</span></article>`).join(''):empty(t('با فرم ارتباط یا درخواست کلاس، یک درخواست نمونه ثبت کن.','Try the contact or class request form to add a sample request.'))}</section>`}
function studentDashboard(){const s=state.students[0];if(!s)return empty(t('ابتدا یک زبان‌آموز نمونه اضافه کن.','Add a sample student first.'));return pageHeading(t('سلام، '+titleStudent(s)+'!','Hello, '+titleStudent(s)+'!'),t('مسیر یادگیری‌ات را دنبال کن.','Keep track of your learning journey.'))+`<div class="metrics">${metric(t('سطح زبان','Language level'),esc(s.level),t('انگلیسی','English'),'book')}${metric(t('کلاس‌های پیش رو','Upcoming classes'),n(state.sessions.filter(x=>x.studentId===s.id&&x.status==='scheduled').length),t('جلسات نمونه','Sample classes'),'calendar')}</div><section class="panel"><div class="panel-head"><h2>${t('کلاس‌های من','My classes')}</h2></div><div class="schedule-list">${sessionList(state.sessions.filter(x=>x.studentId===s.id))}</div></section>`}

function render(){route=location.pathname.replace(/\/$/,'')||'/';query=new URLSearchParams(location.search);document.documentElement.lang=prefs.lang;document.documentElement.dir=prefs.lang==='fa'?'rtl':'ltr';document.documentElement.classList.toggle('dark',prefs.dark);if(/^#[a-f\d]{6}$/i.test(prefs.accent||'')){document.documentElement.style.setProperty('--primary',prefs.accent);document.documentElement.style.setProperty('--brand-primary',prefs.accent)}else{document.documentElement.style.removeProperty('--primary');document.documentElement.style.removeProperty('--brand-primary')}const [view,id]=route.slice(1).split('/');let body;if(workspaceRoutes.includes(view)){const content=view==='dashboard'?dashboard():view==='students'?students(id):view==='schedule'?schedule():view==='finance'?finance():view==='messages'?messages():view==='studio'?studio():view==='journal'?teacherJournal():view==='admin'?admin():studentDashboard();body=workspaceShell(view,content)}else{let page=route==='/'?home():view==='teachers'?(id?teacherPage(id):directory()):view==='blog'?(id?articlePage(id):journal()):view==='contact'?contact():view==='signin'?signin():notFound();body=`<div class="public-site">${header(view||'home')}${page}${footer()}</div>`}app.innerHTML=demoBar()+body;document.title=(route==='/'?'Classer':t('نسخه نمایشی Classer','Classer demo'))+' · '+t('پیش‌نمایش','Preview');updateScroll()}
function navigate(url){closeModal();history.pushState({},'',url);render();window.scrollTo(0,0)}
function updateScroll(){document.querySelector('.pub-header')?.classList.toggle('is-scrolled',scrollY>64);document.querySelector('.pub-back-top')?.classList.toggle('visible',scrollY>300)}
window.addEventListener('scroll',updateScroll,{passive:true});window.addEventListener('popstate',()=>{closeModal();render()});
function closeModal(){overlay.innerHTML='';document.body.classList.remove('modal-open');if(closeModal.previous?.isConnected)closeModal.previous.focus()}
function modal(title,content){closeModal.previous=document.activeElement;overlay.innerHTML=`<div class="demo-modal-backdrop"><section class="demo-modal" role="dialog" aria-modal="true" aria-labelledby="demo-modal-title"><header><h2 id="demo-modal-title">${title}</h2>${button('close',icon('close'),'icon-button',`aria-label="${t('بستن','Close')}"`)}</header>${content}</section></div>`;document.body.classList.add('modal-open');overlay.querySelector('input,textarea,select,button')?.focus()}
document.addEventListener('keydown',e=>{if(!overlay.firstChild)return;if(e.key==='Escape'){e.preventDefault();closeModal()}if(e.key==='Tab'){const items=[...overlay.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);if(!items.length)return;const first=items[0],last=items.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
overlay.addEventListener('click',e=>{if(e.target.classList.contains('demo-modal-backdrop'))closeModal()});
function studentForm(s){return `<form data-form="student" data-id="${esc(s?.id||'')}" class="demo-form"><div class="demo-form-notice">${t('اطلاعات نمونه وارد کنید. حساب واقعی ساخته نمی‌شود.','Use sample details. No real account is created.')}</div>${field(t('نام فارسی','Persian name'),'name',s?.name||'','text','required minlength="2" maxlength="100"')}${field(t('نام انگلیسی','English name'),'nameEn',s?.nameEn||'','text','maxlength="100"')}${field(t('ایمیل نمونه','Sample email'),'email',s?.email||'','email','required maxlength="200"')}<div class="form-grid"><label class="field">${t('سطح','Level')}<select name="level">${options(['A1','A2','B1','B2','C1','C2'].map(x=>[x,x]),s?.level||'A1')}</select></label><label class="field">${t('واحد پول','Currency')}<select name="currency">${options([['TOMAN',t('تومان','Toman')],['USD',t('دلار','USD')]],s?.currency||'TOMAN')}</select></label>${field(t('شهریه جلسه','Fee per class'),'rate',s?.rate??'','number','required min="0" max="100000000" step="0.01"')}${field(t('مدت جلسه، دقیقه','Class duration, minutes'),'duration',s?.duration||60,'number','required min="15" max="300" step="1"')}</div><button class="btn primary">${t('ذخیره زبان‌آموز نمونه','Save sample student')}</button></form>`}
function sessionForm(s){if(!state.students.length){toast(t('ابتدا یک زبان‌آموز اضافه کن.','Add a student first.'));return ''}return `<form data-form="session" data-id="${esc(s?.id||'')}" class="demo-form"><label class="field">${t('زبان‌آموز','Student')}<select name="studentId">${options(state.students.map(x=>[x.id,titleStudent(x)]),s?.studentId||state.students[0].id)}</select></label><div class="form-grid">${field(t('تاریخ','Date'),'date',s?.date||selectedDay,'date','required')}${field(t('ساعت','Time'),'time',s?.time||'10:00','time','required')}${field(t('مدت، دقیقه','Duration, minutes'),'duration',s?.duration||60,'number','required min="15" max="300" step="1"')}<label class="field">${t('نوع کلاس','Class format')}<select name="type">${options([['online',t('آنلاین','Online')],['in-person',t('حضوری','In person')]],s?.type||'online')}</select></label></div><label class="field">${t('وضعیت','Status')}<select name="status">${options(['scheduled','held','cancelled'].map(x=>[x,statusLabel(x)]),s?.status||'scheduled')}</select></label><label class="field">${t('یادداشت جلسه','Class notes')}<textarea name="note" rows="3" maxlength="2000">${esc(s?.note||'')}</textarea></label><p class="muted small">${t('شهریه بر اساس نرخ و مدت پایه زبان‌آموز محاسبه می‌شود.','Fee is calculated from the student’s base rate and duration.')}</p><button class="btn primary">${t('ذخیره جلسه نمونه','Save sample class')}</button></form>`}
function articleForm(a){return `<form data-form="article" data-id="${esc(a?.id||'')}" class="demo-form">${field(t('عنوان مقاله','Post title'),'title',a?.title||'','text','required minlength="3" maxlength="180"')}${field(t('خلاصه','Excerpt'),'excerpt',a?.excerpt||'','text','required maxlength="350"')}<label class="field">${t('دسته‌بندی','Category')}<select name="category">${options(Object.entries(categories).map(([k,v])=>[k,t(...v)]),a?.category||'learning')}</select></label><label class="field">${t('متن مقاله','Post content')}<textarea name="content" rows="8" required minlength="20" maxlength="20000">${esc(a?.content||'')}</textarea></label><label class="field">${t('وضعیت','Status')}<select name="status">${options([['draft',t('پیش‌نویس','Draft')],['published',t('منتشرشده در همین دمو','Published in this demo')]],a?.status||'draft')}</select></label><button class="btn primary">${t('ذخیره نوشته نمونه','Save sample post')}</button></form>`}
document.addEventListener('click',event=>{const a=event.target.closest('a[href]');if(a&&a.origin===location.origin&&!event.ctrlKey&&!event.metaKey&&!event.shiftKey&&event.button===0){event.preventDefault();navigate(a.pathname+a.search);return}const b=event.target.closest('[data-action]');if(!b)return;const id=b.dataset.id,action=b.dataset.action;if(action==='theme'||action==='language'){if(action==='theme')prefs.dark=!prefs.dark;else prefs.lang=prefs.lang==='fa'?'en':'fa';try{storage.setItem(PREF_KEY,JSON.stringify(prefs))}catch{}render();return}if(action==='close')return closeModal();if(action==='top')return window.scrollTo({top:0,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});if(action==='menu')return modal(t('منوی اصلی','Main menu'),[['/','خانه','Home'],['/teachers','معلم‌ها','Teachers'],['/blog','بلاگ','Journal'],['/contact','ارتباط با ما','Contact'],['/signin','دیدن پنل‌ها','Explore dashboards']].map(([url,fa,en])=>link(url,t(fa,en),'demo-menu-link')).join(''));if(action==='workspace-menu')return modal(t('منوی پنل','Dashboard menu'),navItems.map(([key,ic,fa,en])=>link('/'+key,icon(ic)+t(fa,en),'demo-menu-link')).join(''));if(action==='reset')return modal(t('بازنشانی نسخه نمایشی','Reset demo'),`<p>${t('تغییرات همین دمو پاک و اطلاعات نمونه اولیه بازگردانده می‌شوند.','Your changes to this demo will be cleared and the sample data restored.')}</p><div class="demo-modal-actions">${button('confirm-reset',t('بازنشانی دمو','Reset demo'),'btn danger')}${button('close',t('انصراف','Cancel'))}</div>`);if(action==='confirm-reset'){state=initialState(seed);save();closeModal();render();return toast(t('اطلاعات نمونه بازگردانده شد.','Sample data restored.'))}if(action==='category')return navigate(id==='all'?'/blog':'/blog?category='+id);if(action==='request'){const teacher=state.teachers.find(x=>x.id===id);if(teacher)modal(t('درخواست کلاس نمونه','Sample class request'),inquiryForm(teacher));return}if(action==='add-student'||action==='edit-student')return modal(t('پرونده زبان‌آموز نمونه','Sample student profile'),studentForm(state.students.find(x=>x.id===id)));if(action==='add-session'||action==='edit-session'){const form=sessionForm(state.sessions.find(x=>x.id===id));if(form)modal(t('جلسه نمونه','Sample class'),form);return}if(action==='previous-day'||action==='next-day'||action==='today'){selectedDay=action==='today'?tehranDay():addDays(selectedDay,action==='previous-day'?-1:1);render();return}if(action==='add-memo'||action==='edit-memo')return modal(t('یادداشت','Note'),memForm(state.memos.find(x=>x.id===id)));if(action==='delete-memo'){state.memos=state.memos.filter(x=>x.id!==id);save();render();return}if(action==='settle'){const s=state.sessions.find(x=>x.id===id);if(s)s.paid=true;save();render();return toast(t('تسویه نمونه ثبت شد؛ پرداختی انجام نشد.','Sample settlement saved. No payment was made.'))}if(action==='add-article'||action==='edit-article')return modal(t('نوشته نمونه','Sample post'),articleForm(state.articles.find(x=>x.id===id)));if(action==='delete-article'){state.articles=state.articles.filter(x=>x.id!==id);save();render();return}});
document.addEventListener('input',event=>{if(event.target.id==='teacher-search'){filters.query=event.target.value;document.querySelector('#teacher-results').innerHTML=matchingTeachers().map(teacherCard).join('')||empty(t('معلمی پیدا نشد.','No teachers found.'));document.querySelector('#teacher-count').textContent=n(matchingTeachers().length)+' '+t('معلم نمونه','sample teachers')}if(event.target.id==='accent-color'){prefs.accent=event.target.value;document.documentElement.style.setProperty('--primary',prefs.accent);document.documentElement.style.setProperty('--brand-primary',prefs.accent);try{storage.setItem(PREF_KEY,JSON.stringify(prefs))}catch{}}});
document.addEventListener('change',event=>{if(event.target.id==='schedule-day'&&event.target.value){selectedDay=event.target.value;render()}});
document.addEventListener('submit',event=>{const form=event.target;event.preventDefault();if(form.id==='discovery'){const d=new FormData(form);filters.language=d.get('language');filters.format=d.get('format');navigate('/teachers');return}if(!form.dataset.form)return;const d=Object.fromEntries(new FormData(form)),id=form.dataset.id,kind=form.dataset.form;try{if(kind==='inquiry'){state.requests.unshift({id:crypto.randomUUID(),teacherId:id,name:d.name,email:d.email,message:d.message,format:d.format||'',createdAt:new Date().toISOString()});save();closeModal();toast(t('درخواست نمونه در مرورگر ذخیره شد؛ پیامی ارسال نشد.','Sample request saved in this browser. No message was sent.'));form.reset();return}if(kind==='student'){const duration=Number(d.duration),rate=Number(d.rate);if(!Number.isFinite(rate)||rate<0||!Number.isInteger(duration)||duration<15||duration>300)throw Error(t('نرخ و مدت جلسه را بررسی کن.','Check the class fee and duration.'));if(d.currency==='TOMAN'&&!Number.isInteger(rate))throw Error(t('مبلغ تومان باید عدد صحیح باشد.','Toman amounts must be whole numbers.'));if(d.currency==='USD'&&Math.abs(rate*100-Math.round(rate*100))>1e-6)throw Error(t('دلار حداکثر دو رقم اعشار دارد.','USD supports at most two decimal places.'));if(state.students.some(s=>s.id!==id&&s.email.toLowerCase()===d.email.toLowerCase()))throw Error(t('این ایمیل نمونه تکراری است.','This sample email is already in use.'));const old=state.students.find(s=>s.id===id),s={...old,...d,id:id||crypto.randomUUID(),rate,duration,skills:old?.skills||[4,4,4,4],phone:''};if(old)state.students=state.students.map(x=>x.id===id?s:x);else state.students.push(s)}if(kind==='session'){const st=state.students.find(x=>x.id===d.studentId),old=state.sessions.find(x=>x.id===id),duration=Number(d.duration);if(!st||!Number.isInteger(duration)||duration<15||duration>300)throw Error(t('اطلاعات جلسه معتبر نیست.','Invalid class details.'));const [h,m]=d.time.split(':').map(Number);if(h*60+m+duration>1440)throw Error(t('پایان کلاس باید در همین روز باشد.','The class must end on the same day.'));const s={...d,id:id||crypto.randomUUID(),duration,rate:feeFor(old?.baseRate??st.rate,old?.baseDuration??st.duration,duration,old?.currency??st.currency),baseRate:old?.baseRate??st.rate,baseDuration:old?.baseDuration??st.duration,currency:old?.currency??st.currency,paid:old?.paid||false};if(old?.paid&&(s.rate!==old.rate||s.status!=='held'))throw Error(t('برای این جلسه ابتدا باید تسویه نمونه را بازنشانی کنی.','Reset the demo before changing a settled class fee or status.'));if(sessionConflict(state.sessions,s))throw Error(t('این زمان با یک کلاس دیگر تداخل دارد.','This time overlaps another class.'));if(old)state.sessions=state.sessions.map(x=>x.id===id?s:x);else state.sessions.push(s)}if(kind==='memo'){const m={...d,id:id||crypto.randomUUID()};if(id)state.memos=state.memos.map(x=>x.id===id?m:x);else state.memos.push(m)}if(kind==='profile')state.profile={...state.profile,...d};if(kind==='message')state.messages.push({id:crypto.randomUUID(),studentId:id,text:d.text,direction:'out'});if(kind==='article'){const old=state.articles.find(x=>x.id===id);const a={...old,...d,id:id||crypto.randomUUID(),teacherId:'sample-sara',createdAt:old?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString(),sample:true};if(old)state.articles=state.articles.map(x=>x.id===id?a:x);else state.articles.push(a)}save();closeModal();render();toast(t('در نسخه نمایشی همین مرورگر ذخیره شد.','Saved in this browser’s demo.'))}catch(error){toast(error.message)}});
render();
